from pyspark.sql import functions as F

spark.conf.set("spark.sql.adaptive.enabled", "false")  # keep the plan exactly as written


def long_trips(trips, taxi_zones):
    zones = F.broadcast(taxi_zones)  # always send the zones to every task
    long = trips.filter(F.col("trip_distance") > 5)
    return long.join(zones, long.pickup_zone_id == zones.zone_id).select("trip_id", "zone_name", "trip_distance")


def step_counts(df):
    """The rows each plan step produced in df's last run, top step first. It runs nothing itself."""
    steps = []

    def walk(node):
        name = node.nodeName().strip()
        if name == "AdaptiveSparkPlan":
            return walk(node.executedPlan())
        if name.endswith("QueryStage"):
            return walk(node.plan())
        metrics = node.metrics()
        if metrics.contains("numOutputRows"):
            steps.append((name, metrics.apply("numOutputRows").value()))
        children = node.children()
        for i in range(children.size()):
            walk(children.apply(i))

    walk(df._jdf.queryExecution().executedPlan())
    return steps


def as_table(steps):
    rows = [(i + 1, step, n) for i, (step, n) in enumerate(steps)]
    return spark.createDataFrame(rows, "position INT, step STRING, rows LONG")


def solve(trips, taxi_zones):
    lookup = long_trips(trips, taxi_zones)
    # Profile one run of the lookup.
    return as_table(step_counts(lookup))
